'use strict'

function round(value) {
  return Math.round(value * 100) / 100
}

function checked(item) {
  if (!Number.isInteger(item.qty) || item.qty <= 0) {
    throw new Error('quantity must be a positive whole number: ' + String(item.qty))
  }
  return item
}

function subtotal(items) {
  return round(items.map(checked).reduce((sum, item) => sum + item.price * item.qty, 0))
}

function total(items, coupon) {
  const before = subtotal(items)
  if (coupon === undefined) return before
  if (coupon.type === 'percent') return round(before * (1 - coupon.value / 100))
  throw new Error('unknown coupon type: ' + String(coupon.type))
}

function shipping(amount) {
  return amount >= 100 ? 0 : 8
}

module.exports = { subtotal, total, shipping }

